<?php require_once __DIR__.'/config/config.php'; require_once __DIR__.'/includes/functions.php'; $stmt=$pdo->prepare("SELECT * FROM news WHERE slug=? AND status='published'"); $stmt->execute([$_GET['slug']??'']); $item=$stmt->fetch(); if(!$item){http_response_code(404);$pageTitle='Article introuvable';}else{$pageTitle=$item['title'];} include __DIR__.'/includes/header.php'; ?>
<section class="section"><div class="container prose"><?php if($item): ?><span class="eyebrow">ACTUALITÉ · <?=e($item['published_at']?date('d/m/Y',strtotime($item['published_at'])):'')?></span><h1><?=e($item['title'])?></h1><p class="lead"><?=e($item['summary'])?></p><div class="article-content"><?=nl2br(e($item['content']))?></div><?php else: ?><h1>Article introuvable</h1><a href="actualites.php">Retour aux actualités</a><?php endif; ?></div></section>
<?php include __DIR__.'/includes/footer.php'; ?>
